// composables/useTrans.ts
export const useTrans = () => {
    const route = useRoute()
    const locale = route.params.lang as string || 'en'

    // Use a reactive object for translations
    const t = ref<any>({})

    const loadTranslations = async () => {
        try {
            // Dynamically import the json file based on locale
            const messages = await import(`../locales/${locale}.json`)
            t.value = messages.default
        } catch (e) {
            console.error(`Could not load translations for ${locale}`, e)
            // Fallback to English if file doesn't exist
            const fallback = await import(`../locales/en.json`)
            t.value = fallback.default
        }
    }

    // Load immediately
    loadTranslations()

    return { t }
}